svg.script:
function fitName() {
  const text = document.getElementById('full_name');
  const maxWidth = 1200;
  let size = 64;
  text.setAttribute("font-size", size);

  while (text.getBBox().width > maxWidth && size > 28) {
    size -= 2;
    text.setAttribute("font-size", size);
  }
}
fitName();
